            per[o.name] = t
    top = sorted(per.items(), key=lambda kv: -kv[1])[:10]
    result = {"tris": tris, "verts": verts, "top": top, "n": len(per), "render": g["result"]}
except Exception:
    result = {"error": traceback.format_exc()}

